import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class TerminalPanel extends JPanel
    implements ActionListener {
  private JTextField plate =
    new JTextField("NXA 123", 8);
  private JTextField km = new JTextField("5", 5);
  private JLabel result =
    new JLabel("Enter plate and km");
  public TerminalPanel() {
    setLayout(new BorderLayout(8, 8));
    JLabel p = new JLabel("Plate:");
    JLabel d = new JLabel("Distance (km):");
    p.setLabelFor(plate);
    d.setLabelFor(km);
    JButton quote = new JButton("Quote fare");
    quote.addActionListener(this);
    JPanel form = new JPanel(new GridLayout(2, 2, 8, 8));
    form.add(p); form.add(plate);
    form.add(d); form.add(km);
    JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT));
    actions.add(quote);
    add(form, BorderLayout.NORTH);
    add(result, BorderLayout.CENTER);
    add(actions, BorderLayout.SOUTH);
  }
  @Override public void actionPerformed(
      ActionEvent e) {
    try {
      result.setText(FareService.quote(
        plate.getText(), km.getText()));
    } catch (NumberFormatException ex) {
      result.setText("Enter a number for km.");
    } catch (VehicleNotFoundException ex) {
      result.setText(ex.getMessage());
    } catch (InvalidDistanceException ex) {
      result.setText(ex.getMessage());
    }
  }
}

public class BoardingTask implements Runnable {
  private Vehicle vehicle;
  private int[] groups;
  private String result = "not run yet";
  public BoardingTask(Vehicle vehicle, int[] groups) {
    this.vehicle = vehicle;
    this.groups = groups;
  }
  @Override public void run() {
    try {
      for (int g : groups) {
        vehicle.board(g);
        Thread.sleep(50);
      }
      result = "all boarded";
    } catch (OverloadException e) {
      result = "stopped: " + e.getMessage();
    } catch (InterruptedException e) {
      result = "interrupted";
    }
  }
  public String getResult() { return result; }
}

public class Bus extends Vehicle {
    private int seats;

    public Bus(String plateNumber, String driverName, int seats) {
        super(plateNumber, driverName);
        this.seats = seats;
    }

    public int getSeats() { return seats; }

    @Override
    public double computeFare(double km) {
        return 15.00 + (km * 2.50);
    }

    @Override
    public int getCapacity() { return seats; }
}

import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;
public class ConvoyLeg implements Runnable {
  private String plate;
  private int delayMs;
  private CyclicBarrier barrier;
  public ConvoyLeg(String plate, int delayMs, CyclicBarrier barrier) {
    this.plate = plate;
    this.delayMs = delayMs;
    this.barrier = barrier;
  }
  private void driveTo(String stop)
      throws InterruptedException, BrokenBarrierException {
    Thread.sleep(delayMs);
    System.out.println(plate + " arrived at " + stop);
    int stillComing = barrier.await();
    if (stillComing == 0) {
      System.out.println("-- All here at " + stop
        + ". The convoy moves on together!");
    }
  }
  @Override public void run() {
    try {
      driveTo("Monumento");
      driveTo("Recto");
    } catch (InterruptedException | BrokenBarrierException e) {
      System.out.println(plate + " left the convoy: " + e);
    }
  }
}

public class DispatchThread extends Thread {
  private Vehicle vehicle;
  private int trips;
  private double collected = 0;
  private String ranOn = "not run yet";
  public DispatchThread(Vehicle vehicle, int trips) {
    super(vehicle.getPlateNumber());
    this.vehicle = vehicle;
    this.trips = trips;
  }
  @Override public void run() {
    ranOn = Thread.currentThread().getName();
    for (int i = 1; i <= trips; i++) {
      collected = collected + vehicle.quoteFare(5);
      try { Thread.sleep(100); }
      catch (InterruptedException e) { return; }
    }
  }
  public double getCollected() { return collected; }
  public String getRanOn() { return ranOn; }
}

public class FareCheck {
  public static void main(String[] args) {
    String[][] cases = {{"NXA 123", "5"}, {"TRC 456", "2"},
      {"BUS 789", "4"}, {"NYB 321", "6"}, {"nxA 123", " 5 "},
      {"ZZZ", "5"}, {"NXA 123", "abc"}, {"NXA 123", "0"},
      {"NXA 123", "NaN"}, {"NXA 123", "1e309"}};
    for (String[] c : cases) {
      try {
        System.out.println(
          FareService.quote(c[0], c[1]));
      } catch (VehicleNotFoundException |
        NumberFormatException | InvalidDistanceException e) {
        System.out.println(
          e.getClass().getSimpleName() + ": "
          + e.getMessage());
      }
    }
  }
}

import java.util.Locale;
public class FareService {
  public static String quote(
      String plate, String distance)
      throws VehicleNotFoundException {
    double km =
      Double.parseDouble(distance.trim());
    if (!Double.isFinite(km) || km <= 0) {
      throw new InvalidDistanceException(
        "Use a finite km above 0.");
    }
    Vehicle[] fleet = {
      new Jeepney("NXA 123", "Mang Ramon",
        "Monumento-Divisoria"),
      new Tricycle("TRC 456", "Kuya Ben",
        "Bagong Silang TODA"),
      new Bus("BUS 789", "Aling Rosa", 50),
      new Jeepney("NYB 321", "Mang Tonyo",
        "Sangandaan-Recto")
    };
    String key = plate.trim()
      .toUpperCase(Locale.ROOT);
    for (Vehicle v : fleet) {
      if (v.getPlateNumber().equals(key)) {
        double fare = v.quoteFare(km);
        if (!Double.isFinite(fare)) {
          throw new InvalidDistanceException(
            "Distance is too large.");
        }
        return String.format(Locale.ROOT,
          "%s: P%.2f", key, fare);
      }
    }
    throw new VehicleNotFoundException(
      "Unknown plate: " + key);
  }
}

public class InvalidDistanceException extends RuntimeException {
    public InvalidDistanceException(String message) {
        super(message);
    }
}

public class Jeepney extends Vehicle {
    private String route;

    public Jeepney(String plateNumber, String driverName, String route) {
        super(plateNumber, driverName);
        this.route = route;
    }

    public String getRoute() { return route; }

    @Override
    public double computeFare(double km) {
        double extra = Math.max(0, km - 4) * 2.00;
        return 13.00 + extra;
    }

    @Override
    public int getCapacity() { return 20; }
}

import java.util.concurrent.Semaphore;
public class LoadingBay implements Runnable {
  private String plate;
  private int arriveMs;
  private Semaphore bays;
  public LoadingBay(String plate, int arriveMs, Semaphore bays) {
    this.plate = plate;
    this.arriveMs = arriveMs;
    this.bays = bays;
  }
  @Override public void run() {
    try {
      Thread.sleep(arriveMs);
      System.out.println(plate + " arrives. Free bays: " + bays.availablePermits());
      bays.acquire();
      try {
        System.out.println("   " + plate + " is loading in a bay");
        Thread.sleep(400);
        System.out.println("   " + plate + " leaves the bay");
      } finally { bays.release(); }
    } catch (InterruptedException e) {
      System.out.println(plate + " was interrupted");
    }
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Main {
  static JPanel createContent() {
    JPanel root = new JPanel(new BorderLayout(8, 8));
    root.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
    TerminalPanel panel = new TerminalPanel();
    JLabel status = new JLabel("Not checked");
    JButton check = new JButton("Check ready");
    check.addActionListener(new ActionListener() {
      public void actionPerformed(ActionEvent e) {
        check.setEnabled(false);
        status.setText("Checking...");
        new Thread(new ReadyTask(status, check),
          "Readiness").start();
      }
    });
    JPanel ready = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 8));
    ready.add(check); ready.add(status);
    root.add(new JLabel("Vehicle Terminal"), BorderLayout.NORTH);
    root.add(panel, BorderLayout.CENTER);
    root.add(ready, BorderLayout.SOUTH);
    return root;
  }
  public static void main(String[] args) {
    if (GraphicsEnvironment.isHeadless()) {
      System.out.println("No display: GUI not opened.");
      return;
    }
    SwingUtilities.invokeLater(new Runnable() {
      public void run() {
        JFrame frame = new JFrame("Vehicle Terminal");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setContentPane(createContent());
        frame.setSize(720, 320);
        frame.setMinimumSize(new Dimension(520, 300));
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
      }
    });
  }
}

public class OverloadException extends Exception {
    public OverloadException(String message) {
        super(message);
    }
}

import java.util.concurrent.CountDownLatch;
public class ReadyReport implements Runnable {
  private String plate;
  private int delayMs;
  private CountDownLatch latch;
  public ReadyReport(String plate, int delayMs, CountDownLatch latch) {
    this.plate = plate;
    this.delayMs = delayMs;
    this.latch = latch;
  }
  @Override public void run() {
    try {
      Thread.sleep(delayMs);
      System.out.println(plate + " reports: ready");
    } catch (InterruptedException e) {
      System.out.println(plate + " was interrupted");
    } finally { latch.countDown(); }
  }
}

import javax.swing.*;
public class ReadyTask implements Runnable {
  private JLabel status;
  private JButton button;
  public ReadyTask(
      JLabel status, JButton button) {
    this.status = status;
    this.button = button;
  }
  @Override public void run() {
    String message;
    try {
      Thread.sleep(1500);
      message = "Ready: NXA 123";
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      message = "Check interrupted; try again.";
    }
    final String outcome = message;
    SwingUtilities.invokeLater(new Runnable() {
      public void run() {
        status.setText(outcome);
        button.setEnabled(true);
      }
    });
  }
}

