    public abstract double computeFare(double km);
    public abstract int getCapacity();

    public void showInfo() {
        System.out.println(plateNumber + " | Driver: " + driverName
            + " | Passengers: " + passengers + "/" + getCapacity());
    }
}

public class VehicleNotFoundException extends Exception {
    public VehicleNotFoundException(String message) {
        super(message);
    }
}

import java.awt.*;
import javax.swing.*;
public class LayoutDemo {
  public static void main(String[] args) {
    if (GraphicsEnvironment.isHeadless()) {
      System.out.println(
        "No display: GUI not opened.");
      return;
    }
    SwingUtilities.invokeLater(new Runnable() {
      public void run() {
        JPanel row = new JPanel(
          new FlowLayout(FlowLayout.LEFT, 8, 8));
        row.add(new JLabel("Terminal:"));
        row.add(new JButton("Jeepney"));
        row.add(new JButton("Tricycle"));
        row.add(new JButton("Bus"));
        JFrame f = new JFrame(
          "Flow layout practice");
        f.setDefaultCloseOperation(
          JFrame.DISPOSE_ON_CLOSE);
        f.setContentPane(row);
        f.setSize(420, 180);
        f.setLocationRelativeTo(null);
        f.setVisible(true);
      }
    });
  }
}

