import java.awt.*;
import javax.swing.*;
public class ThemeLayoutCheck {
  public static void main(String[] args) {
    SwingUtilities.invokeLater(new Runnable() {
      public void run() {
        JPanel form = new JPanel(
          new GridLayout(2, 2, 6, 6));
        form.add(new JLabel("Item:"));
        form.add(new JTextField("Rice", 8));
        form.add(new JLabel("Quantity:"));
        form.add(new JTextField("2", 8));
        JPanel actions = new JPanel(
          new FlowLayout());
        actions.add(new JButton("Calculate"));
        JPanel root = new JPanel(
          new BorderLayout(6, 6));
        root.add(form, BorderLayout.CENTER);
        root.add(actions, BorderLayout.SOUTH);
        System.out.println("Form controls: "
          + form.getComponentCount());
        System.out.println("Action controls: "
          + actions.getComponentCount());
        System.out.println("Root groups: "
          + root.getComponentCount());
      }
    });
  }
}

